from __future__ import annotations

from typing import Any

from orders.application.catalog_service import CatalogService
from orders.application.errors import OrderNotFound
from orders.application.order_service import OrderService
from orders.controllers.http import Response, not_found, conflict, bad_request, InvalidRequest


class FulfilmentController:
    def __init__(self, service: OrderService, catalog_service: CatalogService) -> None:
        self._service = service
        self._catalog_service = catalog_service

    def handle_packing_slip(self, order_id: str) -> Response:
        try:
            order = self._service.get_order(order_id)
        except OrderNotFound:
            return not_found("order")

        if order.status == "cancelled":
            return conflict(ValueError(f"order {order_id} is cancelled"))

        packing_slip = self._service.get_packing_slip(order_id)
        return Response(200, packing_slip)

    def handle_low_stock(self, threshold: Any) -> Response:
        if type(threshold) is not int or isinstance(threshold, bool) or threshold < 0:
            return bad_request(InvalidRequest("threshold must be a non-negative integer"))
        products = self._catalog_service.get_low_stock_products(threshold)
        return Response(200, {"products": products})

"""Catalogue management and stock."""

from __future__ import annotations

from typing import Any

from orders.application.errors import Conflict, ProductNotFound
from orders.domain.catalog import Product
from orders.infrastructure.catalog import InMemoryProductCatalog
from orders.infrastructure.stock import InMemoryStockRepository


class CatalogService:
    def __init__(self, catalog: InMemoryProductCatalog, stock: InMemoryStockRepository) -> None:
        self._catalog = catalog
        self._stock = stock

    def add_product(self, sku: str, name: str, unit_price_cents: int, on_hand: int = 0) -> Product:
        if self._catalog.get(sku) is not None:
            raise Conflict(f"product {sku} already exists")
        product = Product(sku, name, unit_price_cents)
        self._catalog.add(product)
        self._stock.set(sku, on_hand)
        return product

    def get_product(self, sku: str) -> Product:
        product = self._catalog.get(sku)
        if product is None:
            raise ProductNotFound(sku)
        return product

    def list_active(self) -> list[Product]:
        return [p for p in self._catalog.list_all() if p.active]

    def on_hand(self, sku: str) -> int:
        self.get_product(sku)
        return self._stock.get(sku)

    def get_low_stock_products(self, threshold: int) -> list[dict[str, Any]]:
        active = self.list_active()
        low_stock = [(p.sku, p.name, self._stock.get(p.sku)) for p in active
                     if self._stock.get(p.sku) < threshold]
        low_stock.sort(key=lambda x: (x[2], x[0]))
        return [{"sku": sku, "name": name, "on_hand": on_hand}
                for sku, name, on_hand in low_stock]

