"""Fulfilment endpoints."""

from __future__ import annotations

from typing import Any

from orders.application.catalog_service import CatalogService
from orders.application.errors import OrderNotFound, ProductNotFound
from orders.application.order_service import OrderService
from orders.controllers.http import (Response, not_found, conflict, bad_request, InvalidRequest,
                                     require_str, require_positive_int)


class FulfilmentController:
    def __init__(self, service: OrderService, catalog_service: CatalogService) -> None:
        self._service = service
        self._catalog_service = catalog_service

    def handle_packing_slip(self, order_id: str) -> Response:
        try:
            order = self._service.get_order(order_id)
        except OrderNotFound:
            return not_found("order")

        if order.status == "cancelled":
            return conflict(ValueError(f"order {order_id} is cancelled"))

        packing_slip = self._service.get_packing_slip(order_id)
        return Response(200, packing_slip)

    def handle_low_stock(self, threshold: Any) -> Response:
        if type(threshold) is not int or isinstance(threshold, bool) or threshold < 0:
            return bad_request(InvalidRequest("threshold must be a non-negative integer"))
        products = self._catalog_service.get_low_stock_products(threshold)
        return Response(200, {"products": products})

    def handle_restock(self, request: dict[str, Any]) -> Response:
        try:
            sku = require_str(request, "sku")
            quantity = require_positive_int(request.get("quantity"), "quantity")
        except InvalidRequest as exc:
            return bad_request(exc)
        try:
            result = self._catalog_service.restock(sku, quantity)
        except ProductNotFound:
            return not_found("product")
        return Response(200, result)

    def handle_fulfilment_summary(self) -> Response:
        orders_summary = self._service.get_open_orders_summary()
        low_stock_count = self._catalog_service.count_low_stock_products(5)
        return Response(200, {
            "open_orders": orders_summary["open_orders"],
            "units_to_pick": orders_summary["units_to_pick"],
            "low_stock_products": low_stock_count,
        })

def get_open_orders_summary(self) -> dict[str, int]:
    all_orders = self._orders.list_all()
    open_orders = [o for o in all_orders if o.status != "cancelled"]
    total_units = sum(item.quantity for order in open_orders for item in order.items)
    return {
        "open_orders": len(open_orders),
        "units_to_pick": total_units,
    }

def restock(self, sku: str, quantity: int) -> dict[str, Any]:
    self.get_product(sku)
    new_level = self._stock.get(sku) + quantity
    self._stock.set(sku, new_level)
    return {"sku": sku, "on_hand": new_level}

def count_low_stock_products(self, threshold: int) -> int:
    return len(self.get_low_stock_products(threshold))
